
# workspace=$HOME/rva-chain

# cd $HOME/rva-chain/files/contract.sh
#!/bin/bash

set -euo pipefail
trap 'echo "❌ Script failed on line $LINENO. Press any key to exit..."; read' ERR

cd $HOME/rva-chain && rm -rf $HOME/rva-chain/bsc-genesis-contract


cat $HOME/rva-chain/bsc-genesis-contract || true

# cp -r $HOME/RVA/bsc-genesis-dev3 $HOME/rva-chain/bsc-genesis-contract

# git clone https://github.com/bnb-chain/bsc-genesis-contract.git $HOME/rva-chain/bsc-genesis-contract

cp -r $HOME/rva-chain/bsc-genesis-contract-backup $HOME/rva-chain/bsc-genesis-contract

cd $HOME/rva-chain/bsc-genesis-contract 

rm -rf ./out

export NVM_DIR="$HOME/.nvm"
# Load nvm
[ -s "$NVM_DIR/nvm.sh" ] && \. "$NVM_DIR/nvm.sh"

nvm use v21

npm install


# curl -L https://foundry.paradigm.xyz | bash

curl -L https://foundry.paradigm.xyz | bash

echo 'export PATH="$HOME/.foundry/bin:$PATH"' >> $HOME/.profile

source $HOME/.profile

foundryup
# forge install --no-git --no-commit foundry-rs/forge-std@v1.7.3

forge install foundry-rs/forge-std@v1.7.3 --no-git

# sudo apt install python3-poetry

curl -sSL https://install.python-poetry.org | python3 -
poetry install


nvm install  12.18.3 && nvm use 12.18.3

rm -rf ./out

cat ./out || true


cp $HOME/rva-chain/genesis-nodes-files/validators.js $HOME/rva-chain/genesis-nodes-files/init_holders.js $HOME/rva-chain/genesis-nodes-files/generate.py $HOME/rva-chain/genesis-nodes-files/generate-genesis.js $HOME/rva-chain/bsc-genesis-contract/scripts

cp $HOME/rva-chain/genesis-nodes-files/package.json $HOME/rva-chain/bsc-genesis-contract/package.json

cp $HOME/rva-chain/genesis-nodes-files/BSCValidatorSet.sol $HOME/rva-chain/bsc-genesis-contract/contracts/BSCValidatorSet.sol
# code .



forge test || true


bash scripts/flatten.sh || true

forge build || true
echo

nvm install v21

nvm use v21

npm run generate:dev

echo

# code .


rm -rf $HOME/rva-chain/files/genesis.json

cat $HOME/rva-chain/files/genesis.json || true

cp $HOME/rva-chain/bsc-genesis-contract/genesis.json $HOME/rva-chain/files/genesis.json

exit

# cat $HOME/rva-chain/files/genesis.json

